param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
function Failure-Of($ErrorRecord){$e=$ErrorRecord.Exception;while($e.InnerException){$e=$e.InnerException};$r=[ordered]@{ok=$false;exception=$e.GetType().FullName;message=$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$r.unknown=[int]$e.CharUnknown;$r.index=$e.Index;$r.high=[int]$e.CharUnknownHigh;$r.low=[int]$e.CharUnknownLow;$r.isPair=$e.IsUnknownSurrogate()};if($e -is [Text.DecoderFallbackException]){$r.bytesUnknown=[int[]]$e.BytesUnknown;$r.index=$e.Index};return $r}


[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture

$flags=[Reflection.BindingFlags]'Public,Instance,DeclaredOnly';$methods=@(foreach($method in [Exception].GetMethods($flags)){[ordered]@{name=$method.Name;returnType=$method.ReturnType.FullName;parameters=@($method.GetParameters()|ForEach-Object {$_.ParameterType.FullName});isVirtual=$method.IsVirtual;isFinal=$method.IsFinal;isStatic=$method.IsStatic;declaringType=$method.DeclaringType.FullName;signature=$method.ToString()}})
$owners=@('System.Exception','System.SystemException','System.ArithmeticException','System.DivideByZeroException','System.IndexOutOfRangeException','System.OverflowException','System.InvalidCastException','System.InvalidOperationException','System.FormatException','System.TypeLoadException','System.IO.IOException','System.Runtime.Serialization.SerializationException','System.NullReferenceException','System.ArgumentException','System.ArgumentNullException','System.ArgumentOutOfRangeException','System.Globalization.CultureNotFoundException');$rows=@()
foreach($owner in $owners){$type=[type]$owner;foreach($hasInner in @($false,$true)){$inner=if($hasInner){[Exception]::new('inner-value')}else{$null};$a=[object[]]::new(2);$a[0]='outer-value';$a[1]=$inner;$e=$type.GetConstructor([type[]]@([string],[Exception])).Invoke($a);$rows+=@([ordered]@{owner=$owner;innerPresent=$hasInner;innerIsSupplied=[object]::ReferenceEquals($e.InnerException,$inner);runtimeType=$e.GetType().FullName;unthrownTargetSiteIsNull=($null -eq $e.TargetSite)})}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();methods=$methods;cases=$rows;qualification='NATIVE_DECLARED_EXCEPTION_METHOD_FLAGS_AND_SELECTED_INNER_TYPE_UNTHROWN_TARGETSITE_VALUES_ONLY; CSHARP_MEMBER_HIDING_ACTUAL_STACKS_FULL_METADATA_AND_TASK_ACCEPTANCE_OPEN'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS declared Exception member flags and 34 value cases'
